    pd_case('Draft edits allowed and publication freezes content',function(){global $wpdb;$db=new P\Database($wpdb);$v=new P\StudyVersionRepository($db);$d=pd_definition('01');$d['id']='V_DRAFT';foreach($d['nodes'] as &$n){$n['version_id']='V_DRAFT';if($n['parent_id']==='V_SIMPLE_1')$n['parent_id']='V_DRAFT';}unset($n);$old=pd_definition('01')['id'];foreach($d['nodes'] as &$n){if($n['parent_id']===$old)$n['parent_id']='V_DRAFT';}unset($n);$d['version_number']=2;$vid=$v->draft($d);$d['protocol_metadata']['edited']=true;$v->replaceDraft($vid,$d);$v->publish($d);pd_reject(function()use($v,$d,$vid){$v->replaceDraft($vid,$d);},'IMMUTABLE');});
