    pd_case('CREATE key with changed subject conflicts',function(){global $wpdb;$vid=(new P\StudyVersionRepository(new P\Database($wpdb)))->publish(pd_definition('01'));pd_reject(function()use($vid){pd_owner()->create($vid,array('kind'=>'PARTICIPANT','id'=>'PARTICIPANT_2'),'CREATE_RETRY',array('created_at'=>'2026-10-12T11:00:00Z'));},'CREATE_KEY_REUSED');});
