    pd_case('Identical command replay returns original result after another commit',function(){$id=pd_create()['execution_id'];$c=array('id'=>'SAME','kind'=>'ANSWER','expected_revision'=>0,'data'=>array('question_id'=>'Q_AGE','value'=>40));$r=pd_owner()->dispatch($id,$c);pd_dispatch($id,'ANSWER',array('question_id'=>'Q_WELLBEING','value'=>2));$counts=pd_counts($id);pd_equal($r,pd_owner()->dispatch($id,$c));pd_equal($counts,pd_counts($id));global $wpdb;$t=$wpdb->prefix.'eipsi_engine_execution_commands';$previous=$wpdb->get_var($wpdb->prepare("SELECT result_json FROM `$t` WHERE execution_id=%s AND command_id='SAME'",$id));pd_sql($wpdb->prepare("UPDATE `$t` SET result_json='[]' WHERE execution_id=%s AND command_id='SAME'",$id));try{pd_assert(pd_owner()->dispatch($id,$c)['next_action']['kind']==='OPERATIONAL_ERROR','Corrupt command result accepted');}finally{pd_sql($wpdb->prepare("UPDATE `$t` SET result_json=%s WHERE execution_id=%s AND command_id='SAME'",$previous,$id));}});
